// Shape the fetched HTML like a forwarded newsletter email so the existing
// Gemini curation node can consume it without changes.
const html = $input.first().json.data;
if (!html || html.length < 500) {
  throw new Error('latest.html is empty or too short; did the GitHub Action run?');
}
const m = html.match(/<title>([^<]*)<\/title>/i);
const subject = m ? m[1] : 'Community Signal';
const dateMatch = subject.match(/\d{4}-\d{2}-\d{2}/);
return [{
  json: {
    // mirror the fields your Gmail node exposes; rename to match your flow
    subject,
    from: 'Community Signal <last30days@noreply>',
    source: 'Community Signal',
    date: dateMatch ? dateMatch[0] : new Date().toISOString().slice(0, 10),
    html,
  },
}];
